package solo;
import java.nio.file.*;import java.util.*;import java.util.zip.*;
public final class Final67BackupCheck {
 public static void main(String[]args)throws Exception{Path root=Path.of(args[0]),save=root.resolve("runtime/server/save_files/debug/character_saves/test.txt");Files.createDirectories(save.getParent());Files.createDirectories(root.resolve("backups"));Files.writeString(root.resolve("backups/recuperacao-manual.zip"),"PRESERVAR");Launcher launcher=new Launcher(root);for(int i=0;i<13;i++){Files.writeString(save,"test-progress-"+i);launcher.backup();Thread.sleep(5);}List<Path> files;try(java.util.stream.Stream<Path>s=Files.list(root.resolve("backups"))){files=s.filter(p->p.getFileName().toString().startsWith("personagens-")).sorted().collect(java.util.stream.Collectors.toList());}if(files.size()!=10||!Files.readString(root.resolve("backups/recuperacao-manual.zip")).equals("PRESERVAR"))throw new AssertionError("Backup retention");try(ZipFile z=new ZipFile(files.get(files.size()-1).toFile())){String text=new String(z.getInputStream(z.getEntry("debug/character_saves/test.txt")).readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);if(!text.equals("test-progress-12"))throw new AssertionError("Backup integrity");}launcher.frame.dispose();launcher.worker.shutdown();System.out.println("FINAL67_BACKUP_CONTENTS_LATEST_10_AUTOMATIC_AND_MANUAL_BACKUP_PRESERVED_PASS");System.exit(0);}
}
